import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpiryTest {

    private static final Instant NOW = Instant.parse("2026-10-31T02:00:00Z");

    @Test
    void cancelsOnlyPlacedOrdersOlderThanThirtyDays() {
        OrderRepository repository = new OrderRepository();
        OrderService service = new OrderService(repository, Clock.fixed(NOW, ZoneOffset.UTC));

        Instant old = NOW.minusSeconds(31L * 24 * 3600);
        Instant justInside = NOW.minusSeconds(30L * 24 * 3600 - 60);
        Instant exactlyThirty = NOW.minusSeconds(30L * 24 * 3600);

        Order staleP = new Order("stale-placed", "c", Money.pln(1), old);
        Order staleConfirmed = new Order("stale-confirmed", "c", Money.pln(1), old);
        Order recent = new Order("recent", "c", Money.pln(1), justInside);
        Order boundary = new Order("boundary", "c", Money.pln(1), exactlyThirty);
        staleConfirmed.changeStatus("CONFIRMED");
        repository.save(staleP);
        repository.save(staleConfirmed);
        repository.save(recent);
        repository.save(boundary);

        assertEquals(1, service.expireStale());

        assertEquals("CANCELLED", staleP.status());
        assertEquals("CONFIRMED", staleConfirmed.status());
        assertEquals("PLACED", recent.status());
        assertEquals("PLACED", boundary.status());
        assertEquals(0, service.expireStale());
    }
}
}
